<?php
if(PHP_SAPI!=='cli'){http_response_code(404);exit;}$dbFile='';$json=false;foreach($argv as $arg){if(strpos($arg,'--db=')===0)$dbFile=substr($arg,5);if($arg==='--json')$json=true;}if($dbFile===''||!is_file($dbFile)){fwrite(STDERR,"Uso: php platform_health_check.php --db=/ruta/base.sqlite [--json]\n");exit(2);}require_once __DIR__.'/../inc/platform_health.php';$pdo=new PDO('sqlite:'.$dbFile);$pdo->setAttribute(PDO::ATTR_ERRMODE,PDO::ERRMODE_EXCEPTION);$report=tickex_platform_health_report($pdo);if($json){echo json_encode($report,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE).PHP_EOL;}else{echo 'TICKEX INFRASTRUCTURE HEALTH: '.strtoupper($report['overall']).PHP_EOL;foreach($report['checks'] as $check)echo '['.strtoupper($check['status']).'] '.$check['label'].': '.$check['value'].' — '.$check['detail'].PHP_EOL;}exit($report['counts']['critical']>0?1:0);
